dict(t='गेहूँ के चोकर के मफिन',p='12 मफिन',s='1 मफिन',
i=['1 अंडा','1/2 कप सफ़ेद चीनी','1/3 कप वनस्पति तेल','1 छोटा चम्मच वैनिला एक्सट्रेक्ट','1 कप चावल का पेय (बिना फोर्टिफाइड)','1 1/2 कप मैदा','1/2 कप गेहूँ का चोकर','1 1/2 छोटा चम्मच बेकिंग सोडा','1 कप क्रैनबेरी, ताज़ी या फ्रोज़न','1/2 कप रसभरी (रास्पबेरी), ताज़ी या फ्रोज़न'],
st=['पारंपरिक ओवन को 350°F पर पहले से गरम करें। मफिन टिन में पेपर कप लगाएँ।','एक मिक्सिंग बाउल में अंडा, चीनी, तेल और वैनिला को एक साथ फेंटें। चावल का पेय डालें और मिलाएँ।','एक अलग कटोरे में मैदा, गेहूँ का चोकर और बेकिंग सोडा को छान लें।','सूखी सामग्री को गीली सामग्री में डालें और अच्छी तरह मिलाएँ।','बेरी को मफिन के मिश्रण में धीरे से मिलाएँ।','घोल को 12 मफिन कपों में बाँटें और लगभग 20 मिनट या मफिन के ऊपरी हिस्से के छूने पर वापस उभरने तक बेक करें।'],
h=['स्वस्थ आहार में आंत्र क्रिया को बढ़ावा देने और बड़ी आंत के रोगों को रोकने के लिए भरपूर फाइबर होना चाहिए। मधुमेह वाले लोगों के लिए यह कोलेस्ट्रॉल, रक्तचाप और ग्लूकोज़ के स्तर को सुधारने वाला भी पाया गया है। गेहूँ का चोकर आहार में फाइबर का स्रोत हो सकता है। गेहूँ एक अनाज है जिसे आमतौर पर आटा बनाने के लिए पीसा जाता है। इस प्रक्रिया के दौरान, चोकर कहे जाने वाले छिलके को बाकी अनाज से अलग कर दिया जाता है और इसे विभिन्न खाद्य पदार्थों में उनकी फाइबर सामग्री बढ़ाने के लिए डाला जा सकता है। आमतौर पर यह शुद्ध गेहूँ के चोकर के रूप में बेचा जाता है और किराने की दुकानों में थोक में उपलब्ध होता है। गेहूँ के चोकर को सामान्य गेहूँ के आटे की तरह अलमारी में नहीं रखा जा सकता। यह समय के साथ बासी हो जाता है। ताज़गी बनाए रखने के लिए इसे फ्रिज में रखें। यदि इसका स्वाद कड़वा है, तो संभवतः यह बासी हो गया है और इसे फेंक देना चाहिए। आहार में फाइबर जोड़ने के अलावा, गेहूँ का चोकर आयरन, मैग्नीशियम और बी विटामिन का भी अच्छा स्रोत है। गेहूँ के चोकर को सीरियल या बेक की गई चीज़ों में डालना आसान है। इसे मफिन में डालना आम है, लेकिन इन खाद्य पदार्थों का पोषण मूल्य बढ़ाने के लिए इसे पैनकेक, वैफल, यीस्ट ब्रेड या यहाँ तक कि कुकी में भी डाला जा सकता है। CKD आहार में गेहूँ के चोकर का सेवन संयम से करना चाहिए क्योंकि इसमें पोटैशियम और फॉस्फोरस की मात्रा अधिक होती है। अपने डाइटीशियन से पूछें कि आपके लिए कितना सही है।'],
f=['2 स्टार्च','1 फैट (वसा)']),
